namespace ToneCustoms.ShellStudio.Textures;
public sealed record DdsInfo(bool Valid,uint Height,uint Width,uint MipMaps,string FourCC,long Bytes,bool HasAlpha,bool IsPowerOfTwo);
public sealed class DdsService { public DdsInfo Inspect(string path){using var f=File.OpenRead(path);using var b=new BinaryReader(f);if(new string(b.ReadChars(4))!="DDS ")return new(false,0,0,0,"",f.Length,false,false);var size=b.ReadUInt32();b.ReadUInt32();var h=b.ReadUInt32();var w=b.ReadUInt32();b.ReadUInt32();b.ReadUInt32();var mip=b.ReadUInt32();f.Position=80;var pfFlags=b.ReadUInt32();var four=new string(b.ReadChars(4));var alpha=(pfFlags&1)!=0;return new(size==124,h,w,mip,four,f.Length,alpha,Power(w)&&Power(h));}static bool Power(uint n)=>n>0&&(n&(n-1))==0;public IEnumerable<string> Validate(DdsInfo d){if(!d.Valid)yield return "Invalid DDS header";if(d.Width>4096||d.Height>4096)yield return "Texture exceeds recommended 4096 size";if(d.MipMaps==0)yield return "DDS has no mipmaps";if(!d.IsPowerOfTwo)yield return "DDS dimensions are not power-of-two";if(string.IsNullOrWhiteSpace(d.FourCC))yield return "DDS compression FourCC is empty";} }
